using AegisCore.Application.Platform;
using AegisCore.Domain;
using AegisCore.Domain.Entities;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

namespace AegisCore.API.Controllers;

// P111 Grade Appeals
[ApiController][Route("api/grade-appeals")] [Authorize] public class GradeAppealsController : ControllerBase { private IGradeAppealService _s; public GradeAppealsController(IGradeAppealService s) => _s = s; [HttpPost] public async Task<IActionResult> Submit([FromBody] GradeAppeal appeal, CancellationToken ct) => Ok(await _s.SubmitAsync(appeal, ct)); [HttpGet("student/{studentId:guid}")] public async Task<IActionResult> GetByStudent(Guid studentId, CancellationToken ct) { var a = await _s.GetByStudentAsync(studentId, ct); return Ok(new { total = a.Count, appeals = a }); } [HttpGet("{id:guid}")] public async Task<IActionResult> GetById(Guid id, CancellationToken ct) => Ok(await _s.GetByIdAsync(id, ct)); [HttpPost("{id:guid}/classify")] public async Task<IActionResult> Classify(Guid id, CancellationToken ct) { await _s.ClassifyGroundsAsync(id, ct); return Ok(new { message = "Grounds classified." }); } [HttpPost("{id:guid}/committee-brief")] public async Task<IActionResult> GenerateBrief(Guid id, CancellationToken ct) => Ok(await _s.GenerateCommitteeBriefAsync(id, ct)); [HttpPost("{id:guid}/decision")] public async Task<IActionResult> Decision(Guid id, [FromQuery] string decision, [FromQuery] string? adjustedGrade, CancellationToken ct) { await _s.ProcessDecisionAsync(id, decision, adjustedGrade, ct); return Ok(new { message = "Decision processed." }); } [HttpGet("pending")] public async Task<IActionResult> Pending(CancellationToken ct) { var p = await _s.GetPendingAsync(ct); return Ok(new { total = p.Count, appeals = p }); } }

// P112 Grade Distribution Analysis
[ApiController][Route("api/grade-distributions")] [Authorize] public class GradeDistributionsController : ControllerBase { private IGradeDistributionService _s; public GradeDistributionsController(IGradeDistributionService s) => _s = s; [HttpPost("analyze")] public async Task<IActionResult> Analyze([FromQuery] Guid courseId, [FromQuery] string semester, [FromQuery] Guid? sectionId, CancellationToken ct) => Ok(await _s.AnalyzeAsync(courseId, semester, sectionId, ct)); [HttpGet("course/{courseId:guid}")] public async Task<IActionResult> GetByCourse(Guid courseId, CancellationToken ct) { var d = await _s.GetByCourseAsync(courseId, ct); return Ok(new { total = d.Count, distributions = d }); } [HttpGet("{id:guid}/anomalies")] public async Task<IActionResult> GetAnomalies(Guid id, CancellationToken ct) { var a = await _s.GetAnomaliesAsync(id, ct); return Ok(new { total = a.Count, anomalies = a }); } }

// P113 Plagiarism Detection
[ApiController][Route("api/plagiarism")] [Authorize] public class PlagiarismController : ControllerBase { private IPlagiarismDetectionService _s; public PlagiarismController(IPlagiarismDetectionService s) => _s = s; [HttpPost("scan")] public async Task<IActionResult> Scan([FromQuery] Guid submissionId, [FromQuery] Guid studentId, [FromQuery] Guid assignmentId, [FromQuery] Guid courseId, [FromQuery] string semester, [FromBody] string submissionText, CancellationToken ct) => Ok(await _s.ScanSubmissionAsync(submissionId, studentId, assignmentId, courseId, semester, submissionText, ct)); [HttpGet("assignment/{assignmentId:guid}")] public async Task<IActionResult> GetByAssignment(Guid assignmentId, CancellationToken ct) { var s = await _s.GetByAssignmentAsync(assignmentId, ct); return Ok(new { total = s.Count, scans = s }); } [HttpGet("{id:guid}")] public async Task<IActionResult> GetById(Guid id, CancellationToken ct) => Ok(await _s.GetByIdAsync(id, ct)); }

// P114 Plagiarism API Integration
[ApiController][Route("api/plagiarism-api")] [Authorize] public class PlagiarismApiController : ControllerBase { private IPlagiarismApiService _s; public PlagiarismApiController(IPlagiarismApiService s) => _s = s; [HttpPost("submit")] public async Task<IActionResult> Submit([FromQuery] Guid submissionId, [FromQuery] string provider, CancellationToken ct) { if (!Enum.TryParse<ApiProviderType>(provider, true, out var p)) return BadRequest(); return Ok(await _s.SubmitToProviderAsync(submissionId, p, ct)); } [HttpGet("{id:guid}")] public async Task<IActionResult> GetResult(Guid id, CancellationToken ct) => Ok(await _s.GetResultAsync(id, ct)); [HttpGet("submission/{submissionId:guid}")] public async Task<IActionResult> GetBySubmission(Guid submissionId, CancellationToken ct) { var s = await _s.GetBySubmissionAsync(submissionId, ct); return Ok(new { total = s.Count, submissions = s }); } }

// P115 Convocation Management
[ApiController][Route("api/convocations")] [Authorize] public class ConvocationsController : ControllerBase { private IConvocationService _s; public ConvocationsController(IConvocationService s) => _s = s; [HttpPost] public async Task<IActionResult> Create([FromBody] Convocation convocation, CancellationToken ct) => Ok(await _s.CreateAsync(convocation, ct)); [HttpPost("{id:guid}/check-eligibility")] public async Task<IActionResult> CheckEligibility(Guid id, CancellationToken ct) { var e = await _s.CheckEligibilityAsync(id, ct); return Ok(new { total = e.Count, eligibility = e }); } [HttpPost("{id:guid}/generate-certificates")] public async Task<IActionResult> GenerateCertificates(Guid id, CancellationToken ct) { var c = await _s.GenerateCertificatesAsync(id, ct); return Ok(new { total = c.Count, certificates = c }); } [HttpPost("{convocationId:guid}/check-in/{studentId:guid}")] public async Task<IActionResult> CheckIn(Guid convocationId, Guid studentId, CancellationToken ct) => Ok(await _s.CheckInAsync(convocationId, studentId, ct)); [HttpGet("upcoming")] public async Task<IActionResult> Upcoming(CancellationToken ct) { var u = await _s.GetUpcomingAsync(ct); return Ok(new { total = u.Count, convocations = u }); } }

// P116 Semester Freeze & Deferral
[ApiController][Route("api/freezes")] [Authorize] public class SemesterFreezesController : ControllerBase { private ISemesterFreezeService _s; public SemesterFreezesController(ISemesterFreezeService s) => _s = s; [HttpPost] public async Task<IActionResult> Apply([FromBody] SemesterFreeze freeze, CancellationToken ct) => Ok(await _s.ApplyAsync(freeze, ct)); [HttpGet("{id:guid}")] public async Task<IActionResult> GetById(Guid id, CancellationToken ct) => Ok(await _s.GetByIdAsync(id, ct)); [HttpGet("student/{studentId:guid}")] public async Task<IActionResult> GetByStudent(Guid studentId, CancellationToken ct) { var f = await _s.GetByStudentAsync(studentId, ct); return Ok(new { total = f.Count, freezes = f }); } [HttpPost("{id:guid}/approve")] public async Task<IActionResult> Approve(Guid id, [FromQuery] bool approved, [FromQuery] string? rejectionReason, [FromQuery] Guid? approvedByUserId, CancellationToken ct) { await _s.ProcessApprovalAsync(id, approved, rejectionReason, approvedByUserId, ct); return Ok(new { message = approved ? "Approved." : "Rejected." }); } [HttpPost("{id:guid}/initiate-return")] public async Task<IActionResult> InitiateReturn(Guid id, CancellationToken ct) { await _s.InitiateReturnAsync(id, ct); return Ok(new { message = "Return initiated." }); } }

// P117 Online Exam Proctoring
[ApiController][Route("api/proctoring")] [Authorize] public class ProctoringController : ControllerBase { private IProctoringService _s; public ProctoringController(IProctoringService s) => _s = s; [HttpPost("sessions")] public async Task<IActionResult> CreateSession([FromBody] ProctoringSession session, CancellationToken ct) => Ok(await _s.CreateSessionAsync(session, ct)); [RequestSizeLimit(10 * 1024 * 1024)][HttpPost("sessions/{sessionId:guid}/verify/{studentId:guid}")] public async Task<IActionResult> VerifyEnvironment(Guid sessionId, Guid studentId, CancellationToken ct) => Ok(await _s.VerifyStudentEnvironmentAsync(sessionId, studentId, ct)); [RequestSizeLimit(10 * 1024 * 1024)][HttpPost("records/{recordId:guid}/events")] public async Task<IActionResult> LogEvent(Guid recordId, [FromQuery] string severity, [FromQuery] string eventType, [FromQuery] string? description, CancellationToken ct) { if (!Enum.TryParse<ProctorEventSeverity>(severity, true, out var s)) return BadRequest(); await _s.LogProctorEventAsync(recordId, s, eventType, description, ct); return Ok(new { message = "Event logged." }); } [HttpPost("records/{recordId:guid}/complete")] public async Task<IActionResult> Complete(Guid recordId, CancellationToken ct) => Ok(await _s.CompleteProctoringAsync(recordId, ct)); [HttpGet("sessions/{sessionId:guid}/records")] public async Task<IActionResult> GetRecords(Guid sessionId, CancellationToken ct) { var r = await _s.GetSessionRecordsAsync(sessionId, ct); return Ok(new { total = r.Count, records = r }); } }

// P118 Prerequisite Conflict Detection
[ApiController][Route("api/prerequisite-conflicts")] [Authorize] public class PrerequisiteConflictsController : ControllerBase { private IPrerequisiteConflictService _s; public PrerequisiteConflictsController(IPrerequisiteConflictService s) => _s = s; [HttpPost("detect/{courseId:guid}")] public async Task<IActionResult> Detect(Guid courseId, CancellationToken ct) { var c = await _s.DetectConflictsAsync(courseId, ct); return Ok(new { total = c.Count, conflicts = c }); } [HttpGet("circular")] public async Task<IActionResult> Circular(CancellationToken ct) { var c = await _s.DetectCircularPrerequisitesAsync(ct); return Ok(new { total = c.Count, conflicts = c }); } [HttpPost("simulate")] public async Task<IActionResult> Simulate([FromQuery] string eventType, [FromQuery] Guid changedElementId, CancellationToken ct) { if (!Enum.TryParse<ChangeEventType>(eventType, true, out var t)) return BadRequest(); return Ok(await _s.SimulateChangeAsync(t, changedElementId, ct)); } [HttpGet("unresolved")] public async Task<IActionResult> Unresolved(CancellationToken ct) { var c = await _s.GetUnresolvedConflictsAsync(ct); return Ok(new { total = c.Count, conflicts = c }); } }
